def seed_italian_content(apps, schema_editor):
    with (Path(__file__).parent / '0010_italian_seed.json').open(encoding='utf-8') as handle:
        seed = json.load(handle)
    alias = schema_editor.connection.alias
    for model_name, fields in seed['fields'].items():
        Model = apps.get_model('landing', model_name)
        for item in Model.objects.using(alias).all():
            updates = {}
            for field in fields:
                original = getattr(item, field)
                translated = seed['translations'].get(original)
